import{z as o,x as s,o as E,c as d,q as A,j as n,D as e,d as r,s as i,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"低延迟工程：内核旁路与 FPGA","description":"","frontmatter":{"title":"低延迟工程：内核旁路与 FPGA","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/low-latency-engineering.md","filePath":"quant/low-latency-engineering.md","lastUpdated":1791413859000}'),p={name:"quant/low-latency-engineering.md"};function B(c,a,h,P,D,u){const t=s("Mermaid");return E(),d("div",null,[a[2]||(a[2]=A('<h1 id="低延迟工程-内核旁路与-fpga" tabindex="-1">低延迟工程：内核旁路与 FPGA <a class="header-anchor" href="#低延迟工程-内核旁路与-fpga" aria-label="Permalink to &quot;低延迟工程：内核旁路与 FPGA&quot;">​</a></h1><div class="epigraph"><p>操作系统把网卡中断、系统调用与调度写成通用分时；内核旁路把数据包交给用户态轮询，FPGA 把解析与风控下沉到硬件流水线。目标是抖动，不只是平均延迟。</p><footer>—— 对照 Aldridge, High-Frequency Trading 对系统架构的综述；Intel DPDK 与网卡厂商内核旁路文档；交易所 FPGA 馈送的公开产品说明</footer></div><p><a href="/quant/colocation-microwave">上一课</a>把物理路径停在机笼与城际。<a href="/quant/matching-engine-arch">撮合核</a>已说明核内单线程全序。本课的缺口是<strong>客户主机上、入核之前那几微秒</strong>：内核网络栈、上下文切换、内存分配如何把「同等线长」重新变成不确定到达。后课时钟课测量这些抖动。本课写机制与研究含义，不提供可部署的旁路或 FPGA 交易代码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>标准路径：网卡中断 → 内核协议栈 → socket → 用户进程。每一段都可能被调度器打断，尾部延迟可以比中位高一个数量级。时间优先只认到达全序，尾部才是经济量。内核旁路（如 Onload、DPDK 一类）让用户态直接轮询描述符队列，绕过系统调用与内核拷贝。FPGA 则在网卡或夹层卡上做协议解析、簿的部分更新、甚至预风控，再把事件送给 CPU 或直接回包。问题是：这些技术改变的是谁的抖动分布，会不会把研究用的软件模拟器训到一个永远达不到的执行集合。</p><p><span class="marginnote">内核旁路翻译成大白话：平时网卡的数据要「先交给操作系统管理员登记，再转给你」；旁路就是绕开管理员，你的程序自己蹲在门口收件。省下登记、搬运与排队的时间，代价是自己干管理员的所有活，还要独占一个核来轮询。</span></p><p>回测若用日频或分钟 bar，本课全部无关。事件级回测若假设「看见行情立刻可撤」，等于假设内核旁路 + 核绑定 + 无日志阻塞已经实现。未实现时，模拟器应给撤单一个延迟分布，而不是一个常数 0。Aldridge 的工程章节强调关键路径上禁止锁、禁止分配、禁止磁盘；研究日志若写在同一线程，你测到的是日志系统的延迟。</p><h3 id="确定性比「更低的中位」更值钱" tabindex="-1">确定性比「更低的中位」更值钱 <a class="header-anchor" href="#确定性比「更低的中位」更值钱" aria-label="Permalink to &quot;确定性比「更低的中位」更值钱&quot;">​</a></h3><p>把中位从 8 µs 降到 4 µs，而 99.9 分位仍是 200 µs，FIFO 竞赛里你仍会在微突发中输掉。工程对象是延迟直方图，尤其是与邻居流量、垃圾回收、CPU 频率缩放相关的尾部。Java 一类运行时除非暂停被严格控制，否则不适合核绑定的撮合客户端。这不是语言偏见，是停顿与时间优先不兼容。</p><p><span class="marginnote">直觉类比：时间优先排队像抢高铁座位——平均走路快没用，决定成败的是你偶尔被绊一跤（GC 停顿、上下文切换）的那几次。中位 4 µs 而 99.9 分位 200 µs，意味着一千次里有一次你在门口停顿，胜负就在那一次。</span></p><p><span class="marginnote">FPGA 行情解码可以在卡上输出「已解码的增量事件」。CPU 若仍用非旁路栈收同一组播，两条路径会给出不同到达时钟。必须声明策略看见的是哪一条，否则信号与执行脚不在同一世界。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>关键路径清单：收包 → 解码 → 风控 → 决策 → 组包 → 发送。每一项标注运行位置（CPU 核 / FPGA / 另一进程）与是否共享缓存。核绑定、隔离中断、关闭频率缩放、大页内存，都是为了把操作系统从随机扰动改成近似专用机。测量用硬件时间戳（网卡、PTP）而不是 <code>gettimeofday</code>。对比实验：同一策略逻辑，走内核栈 vs 旁路，报告到达撮合的往返分布——对象是分布，不是「快了多少倍」的营销数字。</p>',13)),(E(),n(l,null,{default:e(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20RX%5B%221%20%E6%94%B6%E5%8C%85%3A%20%E7%BD%91%E5%8D%A1%E7%A1%AC%E4%BB%B6%E6%97%B6%E9%97%B4%E6%88%B3%22%5D%20--%3E%20DEC%5B%222%20%E8%A7%A3%E7%A0%81%3A%20%E4%BA%8C%E8%BF%9B%E5%88%B6%E8%A1%8C%E6%83%85%E8%A7%A3%E6%9E%90%22%5D%0A%20%20DEC%20--%3E%20PRE%5B%223%20%E9%A2%84%E9%A3%8E%E6%8E%A7%3A%20%E9%99%90%E9%A2%9D%20%2F%20%E8%87%AA%E6%88%90%E4%BA%A4%E6%A3%80%E6%9F%A5%22%5D%0A%20%20PRE%20--%3E%20LOGIC%5B%224%20%E5%86%B3%E7%AD%96%3A%20%E7%AD%96%E7%95%A5%E9%80%BB%E8%BE%91%22%5D%0A%20%20LOGIC%20--%3E%20ENC%5B%225%20%E7%BB%84%E5%8C%85%3A%20%E8%AE%A2%E5%8D%95%E7%BC%96%E7%A0%81%22%5D%0A%20%20ENC%20--%3E%20TX%5B%226%20%E5%8F%91%E9%80%81%3A%20%E6%97%81%E8%B7%AF%E7%9B%B4%E5%86%99%E7%BD%91%E5%8D%A1%E9%98%9F%E5%88%97%22%5D%0A%20%20RULE%5B%22%E7%BA%AA%E5%BE%8B%3A%20%E7%A6%81%E9%94%81%20%2F%20%E7%A6%81%E5%88%86%E9%85%8D%20%2F%20%E7%A6%81%E7%A3%81%E7%9B%98%2C%20%E6%AF%8F%E6%AD%A5%E6%A0%87%E8%BF%90%E8%A1%8C%E4%BD%8D%E7%BD%AE%22%5D%20-.-%3E%20RX%0A%20%20RULE%20-.-%3E%20TX%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=A('<p>FPGA 适合稳定、规格化的流水：SBE 解码、价格整数比较、简单的涨跌幅与数量检查。不适合频繁改参数的研究策略。把研究平台与生产关键路径分成两套二进制：研究用可观测性强的语言，生产用抖动受控的实现，用同一内部事件定义对拍。对拍失败时以生产为准去改研究，而不是用研究的「理论单」去指责交易所。</p><h3 id="与-a-股报撤约束同时存在" tabindex="-1">与 A 股报撤约束同时存在 <a class="header-anchor" href="#与-a-股报撤约束同时存在" aria-label="Permalink to &quot;与 A 股报撤约束同时存在&quot;">​</a></h3><p>旁路与 FPGA 不创造额外的合法报撤密度。<a href="/quant/cn-program-trading-rules">程序化规则</a>与<a href="/quant/cn-fee-cancel-ratio">撤单收费</a>把报撤写成监管对象。工程上能发 10 万笔不意味着规则允许。延迟工程的可行集是「在已报告、未触发异常、公平接入」之内压抖动，不是把境外期货做市的报撤曲线搬到沪深股票。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>内核栈为隔离与通用性付税：拷贝、系统调用、调度。旁路用轮询把税换成占用整核的电与机会成本。FPGA 把确定性交给硬件时钟周期，代价是迭代慢、规格绑定、故障模式难调试。对市场质量：客户侧抖动下降，核入口的到达过程更「尖」，连续簿上的速度租金更集中于能付工程固定成本的人——与 Budish 等对军备竞赛的描述同方向，只是战场从光纤移到网卡。</p><p>生产事故里，工程优化本身是风险：驱动 bug、FPGA 映像错误、内核旁路与操作系统补丁不兼容。后课交易所故障会看到客户侧与交易所侧的故障会互相放大；监控必须覆盖「旁路端口无包」而不是只覆盖策略 PnL。</p>',6)),(E(),n(l,null,{default:e(()=>[i(t,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20NIC%5B%22%E7%BD%91%E5%8D%A1%22%5D%20--%3E%20KStack%5B%22%E5%86%85%E6%A0%B8%E5%8D%8F%E8%AE%AE%E6%A0%88%22%5D%0A%20%20NIC%20--%3E%20Bypass%5B%22%E7%94%A8%E6%88%B7%E6%80%81%E8%BD%AE%E8%AF%A2%E6%97%81%E8%B7%AF%22%5D%0A%20%20NIC%20--%3E%20FPGA%5B%22FPGA%20%E8%A7%A3%E7%A0%81%E4%B8%8E%E9%A2%84%E9%A3%8E%E6%8E%A7%22%5D%0A%20%20KStack%20--%3E%20App%5B%22%E7%AD%96%E7%95%A5%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20Bypass%20--%3E%20App%0A%20%20FPGA%20--%3E%20App%0A%20%20App%20--%3E%20Out%5B%22%E7%BB%84%E5%8C%85%E5%8F%91%E9%80%81%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供可编译的内核旁路交易程序、FPGA 抢跑逻辑或绕过会员网关的接入。研究实现用公开规格做解码即可。云上共享内核的虚拟机无法复制托管裸机的抖动承诺，回测不要用云虚拟时钟去校准微秒策略。</p><p><span class="marginnote">常见误区：以为「上了 FPGA 就一定赢」。FPGA 只是把固定流水做到纳秒级稳定，策略一改就要重新综合映像，迭代以天计；映像写错还会瞬间批量违规下单。确定性买的是「不变」，不是「更强」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>低延迟工程的对象是到达抖动的尾部，不是平均延迟的广告数字。</li><li>内核旁路与 FPGA 改变客户侧关键路径，不改变撮合优先规则。</li><li>模拟器必须给「看见→可撤」一个真实延迟分布；A 股还要叠报撤制度。</li><li>出处：Aldridge, <em>High-Frequency Trading</em>；DPDK / 厂商旁路文档；Budish 等对速度竞赛的讨论。</li></ul>',5))])}const m=o(p,[["render",B]]);export{_ as __pageData,m as default};
